-- Out of Station allowance. Idempotent.
--
-- Staff sent on duty away from their station are paid days × the daily rate for their pay grade.
-- Requested and approved like leave (supervisor tier when switched on, then HR), then posted to the
-- GL: Dr the out-of-station expense account, Cr the employee's bank account. Weekends and holidays
-- count (start to end date, both included) and the allowance is not taxed.
--
-- Ids are generated by the application (as employeeleaves does) so the same statements run on MySQL.

-- One daily rate per pay grade, set by the Bank in Out of Station → Setup.
CREATE TABLE IF NOT EXISTS outofstation_rates (
  id          BIGINT        PRIMARY KEY,
  paygrade_id BIGINT        NOT NULL,
  daily_rate  NUMERIC(14,2) NOT NULL,
  updated_by  BIGINT,
  updated_at  TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT outofstation_rates_paygrade_key UNIQUE (paygrade_id)
);

-- daily_rate, amount, paygrade, account and branch are copied onto the request when it is raised, so
-- a later rate or grade change never rewrites a request already in approval or paid.
CREATE TABLE IF NOT EXISTS outofstation_requests (
  id               BIGINT        PRIMARY KEY,
  request_number   VARCHAR(20)   NOT NULL,
  employee         BIGINT        NOT NULL,
  purpose          VARCHAR(255)  NOT NULL,
  location         VARCHAR(150)  NOT NULL,
  date_start       DATE          NOT NULL,
  date_end         DATE          NOT NULL,
  days             INT           NOT NULL,
  paygrade_id      BIGINT,
  daily_rate       NUMERIC(14,2) NOT NULL,
  amount           NUMERIC(14,2) NOT NULL,
  account_no       VARCHAR(50),
  branch           VARCHAR(100),
  status           VARCHAR(30)   NOT NULL DEFAULT 'Draft',
  approval_level   INT           NOT NULL DEFAULT 0,
  requested_by     BIGINT,
  submitted_by     BIGINT,
  submitted_at     TIMESTAMP(0),
  approved_by      BIGINT,
  approved_at      TIMESTAMP(0),
  rejection_reason VARCHAR(500),
  document_ref     VARCHAR(100),
  payment_log      TEXT,
  posted_at        TIMESTAMP(0),
  created_at       TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT outofstation_requests_number_key UNIQUE (request_number)
);

CREATE INDEX IF NOT EXISTS outofstation_requests_employee_idx ON outofstation_requests (employee);
CREATE INDEX IF NOT EXISTS outofstation_requests_status_idx   ON outofstation_requests (status);
CREATE INDEX IF NOT EXISTS outofstation_requests_dates_idx    ON outofstation_requests (date_start, date_end);

-- Status history, one row per transition (submitted, approved, posted, …).
CREATE TABLE IF NOT EXISTS outofstation_log (
  id          BIGINT       PRIMARY KEY,
  request_id  BIGINT       NOT NULL,
  user_id     BIGINT,
  action      VARCHAR(500) NOT NULL,
  status_from VARCHAR(30),
  status_to   VARCHAR(30),
  created_at  TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS outofstation_log_request_idx ON outofstation_log (request_id);

-- Requesting is open to everyone (like leave). These gate the HR side.
INSERT INTO permissions (name, guard_name, created_at, updated_at) VALUES
  ('view_out_of_station',    'api', NOW(), NOW()),
  ('approve_out_of_station', 'api', NOW(), NOW()),
  ('manage_out_of_station',  'api', NOW(), NOW())
ON CONFLICT (name, guard_name) DO NOTHING;

INSERT INTO role_has_permissions (permission_id, role_id)
SELECT p.id, r.id
FROM permissions p
JOIN roles r ON r.name IN ('super-admin', 'admin', 'hr-manager') AND r.guard_name = 'api'
WHERE p.name IN ('view_out_of_station', 'approve_out_of_station', 'manage_out_of_station')
  AND p.guard_name = 'api'
ON CONFLICT (permission_id, role_id) DO NOTHING;
